import astroid

# Edge case: Nested with statements
code1 = """
class A:
    def __enter__(self):
        return "A"
    def __exit__(self, err_type, err, traceback):
        return

class B:
    def __enter__(self):
        return "B"
    def __exit__(self, err_type, err, traceback):
        return

def func():
    with A() as a:
        with B() as b:
            a, b
"""

# Edge case: With statement inside a loop
code2 = """
class C:
    def __enter__(self):
        return "C"
    def __exit__(self, err_type, err, traceback):
        return

for i in range(2):
    with C() as c:
        c
"""

def test_code(code, description):
    print(f"\n{description}")
    print("=" * len(description))
    try:
        module = astroid.parse(code)

        # Find all Name nodes
        name_nodes = list(module.nodes_of_class(astroid.Name))
        print(f"Found {len(name_nodes)} Name nodes")

        # Try to infer each Name node that represents a context manager variable
        for i, node in enumerate(name_nodes):
            # Only try to infer nodes that are likely context manager variables
            if node.name in ['a', 'b', 'c']:
                inferred = list(node.infer())
                print(f"  {node.name}: {inferred}")

    except Exception as e:
        print(f"Error: {e}")

test_code(code1, "Nested with statements")
test_code(code2, "With statement inside a loop")
EOF
